import { Playfair_Display, Roboto } from 'next/font/google'

const playfairDisplay = Playfair_Display({
  subsets: ['latin'],
  variable: '--font-playfair-display',
})

const roboto = Roboto({
  weight: '400',
  subsets: ['latin'],
  variable: '--font-roboto',
})

export default function BlogHeader() {
  return (
    <header className={`${playfairDisplay.variable} ${roboto.variable}`}>
      <h1 style={{ fontFamily: 'var(--font-playfair-display)' }}>My Personal Blog</h1>
      <p style={{ fontFamily: 'var(--font-roboto)' }}>Thoughts, ideas, and musings</p>
    </header>
  )
}
